// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(this));
    }

    function _run(uint256 first, uint256 second) internal {
        first = bound(first, 0, 1000000000000000000000000000000);
        second = bound(second, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(first >= 1 ether && second >= 1 ether && address(this).balance >= (first + second));
        try c.Deposit{value: first}() {} catch { return; }
        try c.Deposit{value: second}() {} catch { return; }
        uint256 bal;
        try c.balances(address(this)) returns (uint256 __r) { bal = __r; } catch { return; }
        assertTrue(bal == (first + second));
    }

    function testFuzz_run(uint256 first, uint256 second) public {
        _run(first, second);
    }

    receive() external payable {}
}
